def pick(key, heading='h3'):
    name, fit, reason, limit, example, url, profile, icon = PICKS[key]
    setup = '{{root}}capabilities/'+profile+'.html#setup' if profile else 'https://github.com/anthropics/skills#claude-code'
    extra = '' if profile else ' <span>Claude setup via the original repository</span>'
    return f'''<article class="best-pick"><header><span class="best-icon" aria-hidden="true">{glyph(key)}</span><span>Individual skill · {'One bounded task tested' if key=='motion-design' else 'Source reviewed'}</span></header><{heading}>{e(name)}</{heading}><p class="best-fit">Best for: {e(fit)}</p><p>{e(reason)}</p><p><strong>Keep in mind:</strong> {e(limit)}</p><p><strong>Try:</strong> {e(example)}</p><div class="best-links"><a href="{setup}">Setup &amp; requirements →</a><a href="{e(url)}" target="_blank" rel="noopener noreferrer">Original skill ↗</a></div>{extra}<p class="best-source">Source checked {DATE}. Native installation not verified here.</p></article>'''

def add_best_skills(pages):
    def page(path, title, description, body):
        pages[path] = dict(path=path, title=title, description=description, body=CSS+body, activeNav='best')
    note = '<aside class="best-note"><strong>Chosen for a job.</strong>“Best” means our editorial pick for the stated task: clear scope, useful instructions and a practical starting point. Source reviewed on '+DATE+'. Only Motion Design has a bounded task comparison here.</aside>'
    method = '<section class="best-method"><h2>How these lists are chosen</h2><p>We read the original instructions and select for task fit, specific guidance and a usable setup route. These are individual skills, even when distributed in a larger repository. We have not run a comparative benchmark across these picks. Repository stars live in <a href="{{root}}popular.html">Popular</a>; they do not determine this selection. <a href="{{root}}how-we-test.html">Read the evidence policy</a>.</p></section>'
    niches = '<div class="best-niches">'+''.join('<a href="{{root}}collections/'+slug+'.html"><span class="best-icon" aria-hidden="true">'+str(len(keys))+' picks</span><h3>'+e(title)+'</h3><p>'+e(desc)+'</p><span>Explore the shortlist →</span></a>' for slug,title,desc,keys,context in LISTS)+'</div>'
    page('collections.html', 'Best AI skills for useful everyday work', 'An editorial starter list and focused AI skill shortlists for design, coding, writing and spreadsheet tasks.', '<header class="best-hero"><div><p class="eyebrow">The SkillLantern shortlist</p><h1>Best skills.<br>Matched to the job.</h1><p class="lede">A few good starting points beat another endless directory. Pick the work you want to do, see why each skill fits, and follow its setup.</p><a href="#overall">Start with the general picks ↓</a></div>'+note+'</header><section id="overall"><div class="best-heading"><h2>Best overall starting points</h2><p>Four useful jobs across writing, data, building and checking. Choose one for your next task; this is not an install-everything bundle.</p></div><div class="best-picks">'+''.join(pick(k) for k in ['doc-coauthoring','xlsx','frontend-design','webapp-testing'])+'</div></section><section><div class="best-heading"><h2>Go deeper into your niche</h2><p>Smaller lists, clearer tradeoffs.</p></div>'+niches+'</section>'+method)
    for slug,title,desc,keys,context in LISTS:
        page('collections/'+slug+'.html', 'Best AI skills for '+title.lower(), desc, '<a class="back-link" href="{{root}}collections.html">← All best-skills lists</a><header class="best-hero"><div><p class="eyebrow">Best skills / '+e(title)+'</p><h1>'+e(title)+'.<br>A focused shortlist.</h1><p class="lede">'+e(desc)+'</p></div>'+note+'</header><p class="lede">'+e(context)+'</p><div class="best-picks">'+''.join(pick(k,'h2') for k in keys)+'</div>'+method+'<div class="best-heading"><h2>Another kind of work?</h2></div>'+niches)
    entry = '<section class="best-entry"><div><h2>A shortlist for the work you do.</h2><p>General picks and focused lists for design, coding, writing and spreadsheets.</p></div><a class="button secondary" href="{{root}}collections.html">Explore Best skills →</a></section>'
    for path in ('index.html', 'skills.html'):
        # Keep the route near the top, before the large discovery grid.
        body = pages[path]['body']
        marker = '<section class="discovery-section"'
        pages[path]['body'] = CSS + (body.replace(marker,entry+marker,1) if marker in body else body+entry)
